const files = ($input.first().json.files || [])
  .filter(f => (f.mimeType || '').startsWith('image/'))
  .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' }))
  .slice(0, 20);
if (files.length < 2) {
  throw new Error('LinkedIn multi-image needs 2-20 images, the folder has ' + files.length + '. For one photo put a link to the file in the image column, not to the folder.');
}
return files.map((f, i) => ({ json: { idx: i, fileId: f.id, name: f.name } }));

const inits = $input.all();
const dls = $('Carousel: download').all();
if (inits.length !== dls.length) {
  throw new Error('Carousel mismatch: ' + inits.length + ' uploads vs ' + dls.length + ' downloads');
}
return inits.map((it, i) => ({
  json: { uploadUrl: it.json.value.uploadUrl, image: it.json.value.image },
  binary: dls[i].binary,
}));

const init = $input.first().json.value;
return [{
  json: { uploadUrl: init.uploadUrl, document: init.document },
  binary: $('Doc: download').first().binary,
}];

const init = $input.first().json.value;
const bin = $('Video: download').first().binary.data;
if (!bin || !bin.data) {
  throw new Error('Video binary unavailable (binary data mode is not in-memory?)');
}
const buf = Buffer.from(bin.data, 'base64');
if (buf.length > 100 * 1024 * 1024) {
  throw new Error('Video is ' + Math.round(buf.length / 1048576) + ' MB. This pipeline stops at 100 MB.');
}
return init.uploadInstructions.map((p, i) => ({
  json: { part: i, uploadUrl: p.uploadUrl },
  binary: { data: {
    data: buf.subarray(p.firstByte, p.lastByte + 1).toString('base64'),
    mimeType: 'application/octet-stream',
    fileName: 'part' + i,
  } },
}));

const norm = v => String(v ?? '').trim();

const MONTHS = {
  jan:1, sty:1, ciy:1, sic:1, feb:2, lut:2, mar:3, ber:3, apr:4, kwi:4, kvi:4,
  may:5, maj:5, tra:5, jun:6, cze:6, che:6, jul:7, lip:7, aug:8, sie:8, ser:8,
  sep:9, wrz:9, ver:9, oct:10, paz:10, zho:10, nov:11, lis:11, dec:12, gru:12, hru:12,
};
const UA = { 'січ':1, 'лют':2, 'бер':3, 'кві':4, 'тра':5, 'чер':6,
             'лип':7, 'сер':8, 'вер':9, 'жов':10, 'лис':11, 'гру':12 };

function monthFromWord(w) {
  w = w.toLowerCase();
  for (const k of Object.keys(UA)) if (w.startsWith(k)) return UA[k];
  const k3 = w.slice(0, 3);
  if (MONTHS[k3]) return MONTHS[k3];
  return 0;
}
const pad = n => String(n).padStart(2, '0');
const mk = (y, m, d) => (y > 1900 && m >= 1 && m <= 12 && d >= 1 && d <= 31)
  ? `${y}-${pad(m)}-${pad(d)}` : '';

// With separators, the FIRST number is the DAY (UA/PL convention).
function toIso(raw) {
  const s = norm(raw);
  if (!s) return '';

  // Google Sheets serial number
  if (/^\d{4,6}$/.test(s)) {
    const d = new Date(Date.UTC(1899, 11, 30) + Number(s) * 86400000);
    return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10);
  }
  // yyyy-mm-dd / yyyy.mm.dd / yyyy/mm/dd
  let m = s.match(/^(\d{4})[-.\/](\d{1,2})[-.\/](\d{1,2})/);
  if (m) return mk(+m[1], +m[2], +m[3]);
  // dd.mm.yyyy / dd/mm/yyyy / dd-mm-yyyy
  m = s.match(/^(\d{1,2})[-.\/](\d{1,2})[-.\/](\d{4})/);
  if (m) return mk(+m[3], +m[2], +m[1]);
  // 5 серпня 2026 / 5 Aug 2026 / 5 sierpnia 2026
  m = s.match(/^(\d{1,2})\s+([^\s,]+)\,?\s+(\d{4})/);
  if (m) { const mo = monthFromWord(m[2]); if (mo) return mk(+m[3], mo, +m[1]); }
  // Aug 5 2026 / August 5, 2026
  m = s.match(/^([^\s\d,]+)\s+(\d{1,2})\,?\s+(\d{4})/);
  if (m) { const mo = monthFromWord(m[1]); if (mo) return mk(+m[3], mo, +m[2]); }
  return '';
}

const today = (typeof $now !== 'undefined' && $now.toFormat)
  ? $now.toFormat('yyyy-MM-dd')
  : new Date().toISOString().slice(0, 10);

// Read from the node that holds the full rows: this node now sits after the id write,
// whose output is the update response, not the queue.
const rows = $('Assign missing ids').all().map(i => i.json).filter(r => norm(r.id));
const ready = rows.filter(r => norm(r.status) === 'ready');

const dated = [], undated = [];
for (const r of ready) {
  const rawDate = norm(r.scheduled_date);
  if (!rawDate) { undated.push(r); continue; }
  const iso = toIso(rawDate);
  if (!iso) { undated.push(r); continue; }   // unreadable date -> normal queue, never lost
  if (iso <= today) dated.push({ r, iso });
  // future date -> not due yet, stays in the sheet
}
dated.sort((a, b) => a.iso.localeCompare(b.iso) || String(a.r.id).localeCompare(String(b.r.id)));

// A dated post owns its day: if anything is due by date, undated rows do not compete.
const ordered = dated.length ? dated.map(x => x.r) : undated;

if (!ordered.length) return [{ json: {} }];
return ordered.map(r => ({ json: r }));

// Backup run guard: continue only if today's slot really was lost.
// Every terminal action stamps posted_at, so "today" is decided by date, not by status alone:
//   pending today  -> a draft is waiting in Telegram right now
//   done today     -> already published
//   skip today     -> does NOT block (13.09.2026): a rejected draft must be
//                     replaced the same day, otherwise one ❌ costs a whole slot.
//                     Timeout path is unaffected: the 20h window expires at 05:00,
//                     so the 09:00 run of that day stamps pending before we look.
// Yesterday's stuck pending must NOT block us: that is exactly the case this run exists for.
// No ready rows at all -> stay silent: the 15:00 run already sent the "queue is empty" alert.
const rows = $input.all().map(i => i.json).filter(r => String(r.id ?? '').trim());
const today = $now.toFormat('yyyy-MM-dd');
const dayOf = v => String(v ?? '').trim().slice(0, 10);
const statusOf = r => String(r.status ?? '').trim().toLowerCase();

const actedToday = rows.some(r =>
  ['pending', 'done'].includes(statusOf(r)) && dayOf(r.posted_at) === today);
const hasReady = rows.some(r => statusOf(r) === 'ready');

return (actedToday || !hasReady) ? [] : [{ json: { backupRun: true, checkedAt: today } }];

// A row with an empty id is invisible to the rest of this workflow: `Pick next row` filters
// it out, and every mark-* node matches rows by id. That silently killed six planned posts.
// So the system fills the column itself instead of asking the human to remember it.
const stamp = Date.now();

return $input.all().map((item, i) => {
  const r = { ...item.json };
  const hasId = String(r.id ?? '').trim() !== '';
  if (!hasId) {
    r.id = 'auto-' + stamp + '-' + (r.row_number ?? i);
  }
  return { json: r };
});

// Preview only: take the first photos of the folder, in the same order the gallery
// will be published in. Returning an empty list is fine, this branch is a dead end and
// `Telegram Approve` is fed from elsewhere.
const MAX = 10;

const files = ($input.first().json.files || [])
  .filter(f => (f.mimeType || '').startsWith('image/'))
  .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' }))
  .slice(0, MAX);

return files.map((f, i) => ({ json: { idx: i, fileId: f.id, name: f.name } }));
